import { PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new Group();
  root.name = 'features-title';
  root.userData.handlers = {};

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const resources = [];
  const timelines = [];
  let loadedTexture = null;
  let disposed = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(new Color(colors.surface)),
    vec3(new Color(colors.ink)),
    smoothstep(0.05, 0.95, uv().y)
  );
  backdropMaterial.side = THREE.DoubleSide;
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const subjectGeometry = new PlaneGeometry(4.6, 2.875);
  const subjectMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.96
  });
  subjectMaterial.side = THREE.DoubleSide;

  const subject = new Mesh(subjectGeometry, subjectMaterial);
  subject.name = 'ceramic-grain-title-surface';
  subject.position.set(0, 0, -0.05);
  root.add(subject);
  resources.push(subjectGeometry, subjectMaterial);

  const accentGeometry = new PlaneGeometry(0.12, 1.65);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  accentMaterial.side = THREE.DoubleSide;

  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.name = 'signal-red-accent';
  accent.position.set(-2.12, 0, 0.12);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    const text = String(item.text ?? '');
    if (!text) continue;

    const textObject = ctx.fontAtlas.createText(text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.name = `text-${item.role ?? 'headline'}`;
    textObject.position.set(0.05, -0.06, 0.2);
    root.add(textObject);

    textObject.traverse?.((child) => {
      if (child.material) resources.push(child.material);
      if (child.geometry) resources.push(child.geometry);
    });
  }

  const imageUrl = config.imageUrl ?? visualSpec.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) return;

      loadedTexture = texture;
      const image = texture.image;
      const width = image?.width || 512;
      const height = image?.height || 320;

      texture.offset.set(0, 0);
      texture.repeat.set(
        Math.min(1, 512 / width),
        Math.min(1, 320 / height)
      );
      texture.needsUpdate = true;

      subjectMaterial.map = texture;
      subjectMaterial.needsUpdate = true;
    });
  }

  root.onBeforeRender = (_renderer, _scene, camera) => {
    if (camera) {
      subject.quaternion.copy(camera.quaternion);
      accent.quaternion.copy(camera.quaternion);
      backdrop.quaternion.copy(camera.quaternion);
    }
  };

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    root.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power3.out' }
  ).to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.48,
    ease: 'power4.out'
  });
  entrance.play();
  timelines.push(entrance);

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) timeline.kill();

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const entry of material) entry?.dispose?.();
      } else {
        material?.dispose?.();
      }
    });

    loadedTexture?.dispose?.();
    root.clear();
  };

  return root;
}

export default createNode;
